        cs=[c for c in range(W) if I[r][c]==5]
        for a,b in zip(cs,cs[1:]):
            pairs.append(('H',r,a,b))
            for c in range(a+1,b): exp.add((r,c))
    for c in range(W):
        rs=[r for r in range(H) if I[r][c]==5]
